alter table public.schoolpro_admission_documents add column if not exists verified boolean not null default false,add column if not exists verified_by uuid,add column if not exists verified_at timestamptz,add column if not exists verification_notes text;
create or replace function public.verify_schoolpro_admission_document(p_document uuid,p_verified boolean,p_notes text default null) returns void language plpgsql security definer set search_path='' as $$declare d public.schoolpro_admission_documents;a public.schoolpro_admissions;begin select * into d from public.schoolpro_admission_documents where id=p_document;select * into a from public.schoolpro_admissions where id=d.application_id;if a.id is null then raise exception 'Document not found';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','admissions_officer','registrar')) then raise exception 'Not authorized';end if;update public.schoolpro_admission_documents set verified=p_verified,verified_by=auth.uid(),verified_at=now(),verification_notes=p_notes where id=p_document;end$$;
create or replace function public.assign_schoolpro_entrance_cbt(p_application uuid,p_test uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.schoolpro_admissions;t public.schoolpro_cbt_tests;att public.schoolpro_candidate_cbt_attempts;begin select * into a from public.schoolpro_admissions where id=p_application;select * into t from public.schoolpro_cbt_tests where id=p_test and school_id=a.school_id;if a.id is null or t.id is null then raise exception 'Application or test not found';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','admissions_officer','registrar','exam_officer')) then raise exception 'Not authorized';end if;insert into public.schoolpro_candidate_cbt_attempts(application_id,test_id,duration_minutes,expires_at,status) values(a.id,t.id,t.duration_minutes,coalesce(t.closes_at,now()+interval '14 days'),'pending') on conflict(application_id,test_id) do update set expires_at=excluded.expires_at,duration_minutes=excluded.duration_minutes returning * into att;update public.schoolpro_admissions set entrance_test_id=t.id,status='exam_scheduled' where id=a.id;if a.guardian_email is not null then perform public.queue_schoolpro_email(a.school_id,a.guardian_email,a.guardian_name,'entrance_exam_invitation','Entrance examination invitation',jsonb_build_object('applicant_name',a.applicant_name,'test_title',t.title,'cbt_token',att.access_token,'expires_at',att.expires_at));end if;return jsonb_build_object('attempt_id',att.id,'token',att.access_token,'expires_at',att.expires_at);end$$;
revoke all on function public.verify_schoolpro_admission_document(uuid,boolean,text),public.assign_schoolpro_entrance_cbt(uuid,uuid) from public,anon;grant execute on function public.verify_schoolpro_admission_document(uuid,boolean,text),public.assign_schoolpro_entrance_cbt(uuid,uuid) to authenticated;